'use strict';
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),crypto=require('node:crypto'),{createRequire}=require('node:module');
const file=path.resolve('miniapp/tests/schedule-service.test.cjs'),original=fs.readFileSync(file,'utf8'),req=createRequire(file);
function helpers(platformOnly=false){const m={exports:{}};const src=platformOnly?original.replace('const TXN_APP_BUDGET = 80;','const TXN_APP_BUDGET = 10000;'):original;vm.runInNewContext(src+'\nmodule.exports={createPlatformLimitedMockDb,seedReady,compatCall,compatUid,compatForm,memberId,seedDir};',{module:m,exports:m.exports,require:n=>n==='node:test'?()=>{}:req(n),Date,console,Buffer});return m.exports;}
function setup(platformOnly=false){const h=helpers(platformOnly),db=h.createPlatformLimitedMockDb();h.seedReady(db,'p1',[{openid:'mgr_openid',roles:['管家']},{openid:'w_openid',roles:['师傅'],trades:['水电']},{openid:'w2_openid',roles:['师傅'],trades:['泥瓦']}]);return{h,db,call:h.compatCall(db)};}
const results=[];
async function record(name,fn){try{results.push({name,...await fn()});}catch(e){results.push({name,replayError:e.message,code:e.code});}}
async function attempt(fn){try{return{result:await fn()};}catch(e){return{code:e.code,message:e.message};}}
(async()=>{
await record('cross_month_update',async()=>{const{h,db,call}=setup();const a=await call('mgr_openid','createSchedule',{projectId:'p1',requestId:'create',form:h.compatForm(h.compatUid('w_openid'),'2026-01-01','2026-01-01')});const before=JSON.stringify(db.getData());const out=await attempt(()=>call('mgr_openid','updateSchedule',{projectId:'p1',scheduleId:a.scheduleId,expectedVersion:1,requestId:'update',form:h.compatForm(h.compatUid('w_openid'),'2026-02-01','2026-02-01'),reason:'cross month'}));return{...out,unchanged:before===JSON.stringify(db.getData())};});
await record('existing_compat_7b_actual_outcome',async()=>{const{h,db,call}=setup();const a=await call('mgr_openid','createSchedule',{projectId:'p1',requestId:'create',form:h.compatForm(h.compatUid('w_openid'),'2026-01-01','2026-12-31')});let writes=0;db.setHooks({beforeWrite:()=>{writes++;}});return{...await attempt(()=>call('mgr_openid','updateSchedule',{projectId:'p1',scheduleId:a.scheduleId,expectedVersion:1,requestId:'update',form:h.compatForm(h.compatUid('w2_openid'),'2026-06-01','2027-05-31','泥瓦'),reason:'same as compat7b'})),peak:db.getPeakAttemptOps(),attemptedWrites:writes};});
for(const platformOnly of [false,true])await record('26_buckets_same_dates_change_trade_worker_'+(platformOnly?'platform100_only':'fixture80'),async()=>{const{h,db,call}=setup(platformOnly);const a=await call('mgr_openid','createSchedule',{projectId:'p1',requestId:'create',form:h.compatForm(h.compatUid('w_openid'),'2026-01-02','2027-01-01')});const before=JSON.stringify(db.getData());let writes=0;db.setHooks({beforeWrite:()=>{writes++;}});const out=await attempt(()=>call('mgr_openid','updateSchedule',{projectId:'p1',scheduleId:a.scheduleId,expectedVersion:1,requestId:'update',form:h.compatForm(h.compatUid('w2_openid'),'2026-01-02','2027-01-01','泥瓦'),reason:'26 distinct trade-month buckets'}));return{...out,peak:db.getPeakAttemptOps(),attemptedWrites:writes,unchanged:before===JSON.stringify(db.getData())};});
await record('generation0_with_existing_active_removal',async()=>{const{h,db,call}=setup();db.mutate(d=>{d.schedules.s_existing={_id:'s_existing',projectId:'p1',workerUserId:h.compatUid('w_openid'),status:'active',trade:'水电'};});const out=await attempt(()=>call('mgr_openid','removeMember',{projectId:'p1',userId:h.compatUid('w_openid')}));const d=db.getData();return{...out,memberStatus:d.project_members[h.memberId('p1',h.compatUid('w_openid'))].status,remainingActive:Object.values(d.schedules).filter(s=>s.status==='active').length};});
for(const action of ['approveInvitation','assignManager'])await record('maintenance_'+action,async()=>{const{h,db,call}=setup();const {APPID}=req('../cloudfunctions/memberAccess/service');const synthetic='1234567890',target=h.compatUid('w_openid');db.mutate(d=>{d.projects.p1.scheduleWriteMode='maintenance';d.users[target].bindingCodeHash=crypto.createHash('sha256').update(APPID+':'+synthetic).digest('hex');d.users[target].bindingCodeExpiresAt='2030-01-01T00:00:00.000Z';d.invitations.i_test={_id:'i_test',projectId:'p1',status:'requested',applicantUserId:target,role:'设计师',trades:[],expiresAt:'2030-01-01T00:00:00.000Z',version:2};});const out=await attempt(()=>call('mgr_openid',action,{projectId:'p1',invitationId:'i_test',applicantNumber:synthetic,bindingNumber:synthetic}));const d=db.getData();return{...out,epoch:d.projects.p1.scheduleEpoch,mode:d.projects.p1.scheduleWriteMode,roles:d.project_members[h.memberId('p1',target)].roles};});
await record('mixed_external_snapshot_before_scan',async()=>{const{h,db,call}=setup();let changed=false;const target=h.compatUid('w_openid');db.setHooks({beforeRead:(name,key)=>{if(!changed&&name==='member_task_guard'&&key==='p1:'+target){changed=true;db.mutate(d=>{d.projects.p1.scheduleEpoch++;d.project_members[h.memberId('p1',target)].taskDirGeneration=1;d.member_task_guard[key]={_id:key,projectId:'p1',userId:target,schemaVersion:1,generation:1,activeScheduleIds:[],activeScheduleCount:0,version:1,fenceVersion:1};});}}});return{...await attempt(()=>call('mgr_openid','createSchedule',{projectId:'p1',requestId:'create',form:h.compatForm(target,'2026-01-01','2026-01-01')})),attempts:db.getTotalAttempts()};});
await record('committed_receipt_blocked_by_later_guard_loss',async()=>{const{h,db,call}=setup();const body={projectId:'p1',requestId:'create',form:h.compatForm(h.compatUid('w_openid'),'2026-01-01','2026-01-01')};const first=await call('mgr_openid','createSchedule',body);db.mutate(d=>{delete d.member_task_guard['p1:'+h.compatUid('w_openid')];});return{first,...await attempt(()=>call('mgr_openid','createSchedule',body))};});
await record('fixture_first_where_not_rejected',async()=>{const{db}=setup();return await attempt(()=>db.runTransaction(tx=>tx.collection('schedules').where({projectId:'p1'}).get()));});
await record('receipt_replay_mode_changed_after_collect',async()=>{const{h,db,call}=setup();const body={projectId:'p1',requestId:'create',form:h.compatForm(h.compatUid('w_openid'),'2026-01-01','2026-01-01')};await call('mgr_openid','createSchedule',body);const originalTransaction=db.runTransaction;db.runTransaction=async work=>{db.mutate(d=>{d.projects.p1.scheduleWriteMode='maintenance';d.projects.p1.scheduleEpoch++;});return originalTransaction(work);};return{...await attempt(()=>call('mgr_openid','createSchedule',body)),mode:db.getData().projects.p1.scheduleWriteMode};});
const out={recordedAt:new Date().toISOString(),scope:'offline synthetic in-memory only; no cloud or real binding credentials',results};fs.writeFileSync(path.join(process.env.TEMP || require('node:os').tmpdir(),'yf-compat-review-rerun.json'),JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify(out,null,2));
})().catch(e=>{console.error(e);process.exitCode=1;});


